/**
 * Goldens for the commodity projection (DATA-06, D-13, T-02-06).
 *
 * `tests/golden/content/commodities.json` is generated by running the CLI in the
 * container and copying the published values — never typed from memory. This
 * suite pins the parts a regenerated fixture could otherwise hide: the five
 * anchor rows, the unit tags, integer decicredit averages, authored-precision
 * trade ratios, and Alien Items being present but never tradeable.
 */

import { readFileSync } from "node:fs";

import { describe, expect, it } from "vitest";

import { CommoditySchema } from "../../../src/content/schemas/commodity.js";
import type { Commodity } from "../../../src/content/schemas/commodity.js";
import { parseOpenStep } from "../openstep/parser.js";
import { compileCommodities } from "./commodities.js";

interface CommodityFixture {
  readonly version: number;
  readonly commodities: Commodity[];
}

const PLIST = "third_party/oolite/Config/trade-goods.plist";
const DESCRIPTIONS_PLIST = "third_party/oolite/Config/descriptions.plist";

const fixture = JSON.parse(
  readFileSync(
    new URL("../../../tests/golden/content/commodities.json", import.meta.url),
    "utf8",
  ),
) as CommodityFixture;

const source = readFileSync(
  new URL(
    "../../../third_party/oolite/Config/trade-goods.plist",
    import.meta.url,
  ),
  "utf8",
);

const descriptions = parseOpenStep(
  readFileSync(
    new URL(
      "../../../third_party/oolite/Config/descriptions.plist",
      import.meta.url,
    ),
    "utf8",
  ),
  DESCRIPTIONS_PLIST,
);

const commodities = compileCommodities(
  parseOpenStep(source, PLIST),
  descriptions,
);

function require(key: string): Commodity {
  const record = commodities.find((item) => item.key === key);
  if (record === undefined) throw new Error(`commodity "${key}" is missing`);
  return record;
}

describe("commodity golden", () => {
  it("emits the pinned 17-record array", () => {
    expect(fixture.version).toBe(1);
    expect(commodities).toHaveLength(17);
    // Deep equality against the committed fixture, including field order in
    // canonical JSON terms and every authored decimal.
    expect(commodities).toEqual(fixture.commodities);
  });

  it("pins the five anchor rows by value", () => {
    expect(require("food").priceAverage).toBe(50);
    expect(require("gold").unit).toBe("kg");
    expect(require("gold").priceAverage).toBe(388);
    expect(require("platinum").unit).toBe("kg");
    expect(require("platinum").priceAverage).toBe(718);
    expect(require("gem_stones").unit).toBe("g");
    expect(require("gem_stones").priceAverage).toBe(196);
    expect(require("alien_items").tradeable).toBe(false);
  });

  it("resolves display names from descriptions.plist and keeps the key as identity", () => {
    expect(require("food").name).toBe("Food");
    expect(require("liquor_wines").name).toBe("Liquor/Wines");
    expect(require("gem_stones").name).toBe("Gem-Stones");
    expect(require("alien_items").name).toBe("Alien Items");
    for (const record of commodities) {
      // A raw localization token must never reach the screen (D-21).
      expect(record.name).not.toMatch(/^\[commodity-name /);
    }
  });

  it("projects both economy peaks onto every record", () => {
    expect(require("food").peakExport).toBe(7);
    expect(require("food").peakImport).toBe(0);
    expect(require("narcotics").peakExport).toBe(0);
    expect(require("narcotics").peakImport).toBe(0);
    expect(require("alien_items").peakExport).toBe(0);
    expect(require("alien_items").peakImport).toBe(7);
    for (const record of commodities) {
      expect(Number.isInteger(record.peakExport)).toBe(true);
      expect(Number.isInteger(record.peakImport)).toBe(true);
      expect(record.peakExport).toBeGreaterThanOrEqual(0);
      expect(record.peakExport).toBeLessThanOrEqual(7);
      expect(record.peakImport).toBeGreaterThanOrEqual(0);
      expect(record.peakImport).toBeLessThanOrEqual(7);
    }
  });

  it("tags every unit as t, kg or g with pod metadata carried but not applied", () => {
    for (const record of commodities) {
      expect(["t", "kg", "g"]).toContain(record.unit);
    }
    expect(require("food").unit).toBe("t");
    // 0=t, 1=kg, 2=g; the metadata is carried for Phase 5 and never applied here.
    expect(require("food").podConversion.kilogramsPerUnit).toBe(1000);
    expect(require("gold").podConversion.kilogramsPerUnit).toBe(1);
    expect(require("gem_stones").podConversion.kilogramsPerUnit).toBe(0.001);
  });

  it("keeps priceAverage an integer decicredit and the five ratios authored reals", () => {
    for (const record of commodities) {
      expect(Number.isInteger(record.priceAverage)).toBe(true);
      expect(Number.isFinite(record.priceEconomic)).toBe(true);
      expect(Number.isFinite(record.priceRandom)).toBe(true);
      expect(Number.isFinite(record.quantityAverage)).toBe(true);
      expect(Number.isFinite(record.quantityEconomic)).toBe(true);
      expect(Number.isFinite(record.quantityRandom)).toBe(true);
    }
    // Exact literals: 13.5 must not become 13, 0.55 must not become 0.5.
    expect(require("food").priceEconomic).toBe(0.55);
    expect(require("food").priceRandom).toBe(0.04);
    expect(require("food").quantityAverage).toBe(13.5);
    expect(require("food").quantityEconomic).toBe(0.52);
    expect(require("food").quantityRandom).toBe(0.04);
  });

  it("orders by ascending unique sort_order from 100 to 1700", () => {
    expect(commodities.map((record) => record.sortOrder)).toEqual([
      100, 200, 300, 400, 500, 600, 700, 800, 900, 1000, 1100, 1200, 1300, 1400,
      1500, 1600, 1700,
    ]);
  });

  it("keeps alien_items present with zero quantities and exactly one untradeable record", () => {
    const alien = require("alien_items");
    expect(alien.quantityAverage).toBe(0);
    expect(alien.quantityEconomic).toBe(0);
    expect(alien.quantityRandom).toBe(0);
    expect(alien.tradeable).toBe(false);

    const tradeable = commodities
      .filter((record) => record.tradeable)
      .map((record) => record.key)
      .sort();
    const expected = commodities
      .map((record) => record.key)
      .filter((key) => key !== "alien_items")
      .sort();
    expect(tradeable).toEqual(expected);
    expect(commodities.filter((record) => !record.tradeable)).toHaveLength(1);
  });

  it("validates every record with the strict schema and rejects unknown keys", () => {
    for (const record of commodities) {
      expect(CommoditySchema.safeParse(record).success).toBe(true);
    }
    const first = commodities[0];
    if (first === undefined) throw new Error("no commodities emitted");
    expect(CommoditySchema.safeParse({ ...first, extra: true }).success).toBe(
      false,
    );
  });
});
